  if(!files?.length){clearResourceMaterial();return;}
  if(!c.project){fail("先选择项目，再选择文本文件。");return;}
  if(files.length!==1){fail("一次只能选择一个文本文件。");return;}
  const file=files[0];
  const format = /\.(txt|md|csv|json)$/i.exec(file.name)?.[1].toLowerCase();
